function mountainWindWarningMeta(gust:number){if(!Number.isFinite(gust))return undefined;const kmh=gust*1.852,entry=[...DWD_WIND_THRESHOLDS_KMH].reverse().find(item=>kmh>=item.threshold);return entry?{className:`mountain-wind-warning-${entry.threshold}`,label:`${entry.label} ab ${entry.threshold} km/h`}:undefined}
function mountainPrecipitationClass(amount:number){if(!Number.isFinite(amount)||amount<=.05)return'';if(amount<.5)return'mountain-precip-trace';if(amount<2)return'mountain-precip-light';if(amount<5)return'mountain-precip-moderate';return'mountain-precip-heavy'}
