    score-=Math.max(0,safeGust-18)*1.8;if(Number.isFinite(visibility))score-=visibility<1000?42:visibility<4000?20:visibility<10000?7:0;score-=Math.max(0,safeProbability-35)*.45;score-=Math.max(0,safePrecip)*8;score-=safeCape>1200?30:safeCape>700?18:safeCape>350?8:0;if(Number.isFinite(temp))score-=temp>25?Math.min(22,(temp-25)*3):temp<0?14:temp<5?5:0;score+=isDay?3:-4;
