       {showRainBars&&p.map((x,i)=>{const x0=xAt(i),barWidth=Math.max(5,plotW/Math.max(24,p.length)-4),barLeft=Math.max(left,x0-barWidth/2),barRight=Math.min(W-right,x0+barWidth/2),parts=precipSeries[i],type=parts.type,totalTop=yRain(parts.total);if(!isDetailPrecipType(type))return <g key={x.time}/>;const visible=visiblePrecipLegendTypes.includes(type),fill=visible?precipMeta[type].fill:'';return <g key={x.time}>{parts.total>.001&&visible&&barRight>barLeft&&<rect x={barLeft} y={totalTop} width={barRight-barLeft} height={Math.max(1,rainBottom-totalTop)} rx="2" fill={fill}/>}</g>})}
       {showTemperature&&<path d={areaPath} fill="url(#tempFill)"/>}
       {showApparent&&<path d={apparentPath} fill="none" stroke="var(--apparent-line)" opacity="0.96" strokeDasharray="8 6" strokeWidth="2" vectorEffect="non-scaling-stroke"/>}
