       {showTemperature&&<path d={tempPath} fill="none" stroke="#ff7a37" strokeWidth="2.2" vectorEffect="non-scaling-stroke"/>}
       {showPressure&&<path d={pressurePath} fill="none" stroke="#c48cff" strokeWidth="1.4" vectorEffect="non-scaling-stroke"/>}
       {showProbability&&<g className="detail-probability-line" pointerEvents="none"><path className="detail-probability-halo" d={probabilityPath} fill="none" stroke="var(--detail-probability-halo)" strokeWidth="4.6" strokeDasharray="6 5" strokeLinecap="round" strokeLinejoin="round" opacity="0.82" vectorEffect="non-scaling-stroke"/><path d={probabilityPath} fill="none" stroke="#56d7ff" strokeWidth="2.2" strokeDasharray="6 5" strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke"/></g>}
       {showWind&&<path d={windPath} fill="none" stroke="#4fc985" strokeWidth="2" vectorEffect="non-scaling-stroke"/>}
